  <param name="params">{&quot;command&quot;: &quot;cat &gt; /tmp/stage1_renderer.py &lt;&lt; &apos;EOF&apos;
import re
from pathlib import Path

path = Path(&apos;/root/kfmv4/src/client/engine/v2/renderer.ts&apos;)
