# 找到裁切逻辑的位置，替换为支持 clipZone 的版本
old_clip = &apos;&apos;&apos;    // 裁剪（滚动容器必须裁剪子元素）
    if (box.overflow === &apos;hidden&apos; || box.scrollable) {
      const _fh = (box as any)._fullHeight;
      const clipY = (_fh &amp;&amp; box.height &lt; _fh) ? bounds.y - _fh : bounds.y;
      const clipH = (_fh &amp;&amp; box.height &lt; _fh) ? _fh * 2 : bounds.height;
      this.ctx.beginPath();
      this.ctx.roundRect(bounds.x, clipY, bounds.width, clipH, box.borderRadius);
      this.ctx.clip();
    }&apos;&apos;&apos;

new_clip = &apos;&apos;&apos;    // 裁剪（优先使用静态 clipZone，否则用动态 bounds）
    if (box.clipZone) {
      // 静态裁切区域（不受动态 bounds 影响）
      this.ctx.beginPath();
      this.ctx.roundRect(box.clipZone.x, box.clipZone.y, box.clipZone.width, box.clipZone.height, box.borderRadius);
      this.ctx.clip();
    } else if (box.overflow === &apos;hidden&apos; || box.scrollable) {
      // 动态裁切（原有逻辑）
      this.ctx.beginPath();
      this.ctx.roundRect(bounds.x, bounds.y, bounds.width, bounds.height, box.borderRadius);
      this.ctx.clip();
    }&apos;&apos;&apos;

if &apos;box.clipZone&apos; not in content:
    content = content.replace(old_clip, new_clip)
    print(&apos;renderer.ts: clipZone support added&apos;)
else:
    print(&apos;renderer.ts already has clipZone support&apos;)

path.write_text(content)
